hydrator = r'''async function hydrateCompletedInterpretations(jobs){const targets=jobs.filter(job=>{const interpretation=job.interpretation;if(!interpretation||typeof interpretation!=="object"||Array.isArray(interpretation)||interpretationCache.has(job.id)||interpretation.available!==true)return false;const status=String(interpretation.status||"unknown"),shouldHydrate=status==="completed"||status==="failed"||status==="processing";return shouldHydrate&&Boolean(interpretation.fullDetailsUrl||interpretation.detailsUrl)});if(!targets.length)return 0;const failures=[];await Promise.all(targets.map(async job=>{const detailsUrl=safeRelativeUrl(job.interpretation.fullDetailsUrl||job.interpretation.detailsUrl);if(!detailsUrl){interpretationCache.set(job.id,null);failures.push(job);return}try{const payload=await requestJson(detailsUrl,{cache:"no-store"});if(!payload||typeof payload!=="object"||Array.isArray(payload))throw new Error("Malformed interpretation details");interpretationCache.set(job.id,payload)}catch{interpretationCache.set(job.id,null);failures.push(job)}}));renderJobs(jobs);if(failures.length){const job=failures[0];setJobsMessage(`${job.title||job.original_filename||"Audio job"}: editable-draft details could not be loaded. Raw transcription and any previous artifacts remain available.`,true)}return failures.length}
'''
